.padding-bottom { padding-top: 0; padding-right: 0; padding-left: 0; }
.padding-vertical { padding-right: 0; padding-left: 0; }
.spacer-xsmall { width: 100%; padding-top: 0.5rem; }
.spacer-small { width: 100%; padding-top: 1rem; }
.spacer-large { width: 100%; padding-top: 3rem; }
.spacer-xlarge { width: 100%; padding-top: 4rem; }
.hide { display: none; }
.pointer-events-none { pointer-events: none; }
.z-index-1 { position: relative; z-index: 1; }
.z-index-2 { position: relative; z-index: 2; }
.styleguide_box { display: flex; justify-content: center; align-items: center; min-height: 4rem; padding-top: 0.75rem; padding-right: 0.75rem; padding-bottom: 0.75rem; padding-left: 0.75rem; border-top-left-radius: var(--radius--small); border-top-right-radius: var(--radius--small); border-bottom-left-radius: var(--radius--small); border-bottom-right-radius: var(--radius--small); background-color: var(--neutral--darker); font-family: var(--font--heading); font-size: 0.75rem; color: var(--neutral--light); text-align: center; }
.styleguide_box.is-accent { background-color: var(--christine--primary); color: var(--neutral--darkest); }
.styleguide_spacing { display: flex; align-items: flex-start; column-gap: 0.75rem; row-gap: 0.75rem; flex-wrap: wrap; }
.styleguide_spacing-item { min-width: 3rem; background-color: var(--christine--darker); border-top-left-radius: var(--radius--small); border-top-right-radius: var(--radius--small); border-bottom-left-radius: var(--radius--small); border-bottom-right-radius: var(--radius--small); }
@media screen and (max-width: 991px) { .padding-section-large { padding-top: 6rem; padding-bottom: 6rem; } .grid-2 { grid-template-columns: minmax(0, 1fr); column-gap: 3rem; } .hide-tablet { display: none; } }
@media screen and (max-width: 767px) { .padding-section-large { padding-top: 4rem; padding-bottom: 4rem; } .padding-section-small { padding-top: 2rem; padding-bottom: 2rem; } .hide-mobile-landscape { display: none; } }
@media screen and (max-width: 479px) { .hide-mobile-portrait { display: none; } }
